xpath.attribute:
() => {
                if (this.env.isSmall) {
                    this._openAppMenuSidebar();
                    return;
                }
                const homeMenu = this.hm || (this.env.services && this.env.services.home_menu);
                if (homeMenu && homeMenu.toggle) {
                    homeMenu.toggle(true);
                }
            }
